#### Phase 3: Application, Authorization & Data Security (Weeks 11-16)

**Week 11-12: Input Validation & Secure Coding**

**Step 3.1: Implement Comprehensive Input Validation**

```csharp
// FluentValidation for input validation (Layer 5: Application Security)
using FluentValidation;

public class CreateClaimRequest
{
    public string ClaimId { get; set; }
    public string MemberId { get; set; }
    public string ProviderId { get; set; }
    public DateTime ServiceDate { get; set; }
    public decimal Amount { get; set; }
    public string DiagnosisCode { get; set; }
}

public class CreateClaimRequestValidator : AbstractValidator<CreateClaimRequest>
{
    public CreateClaimRequestValidator()
    {
        // ClaimId validation - alphanumeric only, 10-20 characters
        RuleFor(x => x.ClaimId)
            .NotEmpty().WithMessage("ClaimId is required")
            .Length(10, 20).WithMessage("ClaimId must be 10-20 characters")
            .Matches(@"^[a-zA-Z0-9]+$").WithMessage("ClaimId must be alphanumeric");

        // MemberId validation - prevent SQL injection
        RuleFor(x => x.MemberId)
            .NotEmpty()
            .Length(9, 11)
            .Matches(@"^[0-9]+$").WithMessage("MemberId must be numeric");

        // ServiceDate validation - cannot be in future
        RuleFor(x => x.ServiceDate)
            .NotEmpty()
            .LessThanOrEqualTo(DateTime.UtcNow).WithMessage("ServiceDate cannot be in the future")
            .GreaterThan(DateTime.UtcNow.AddYears(-5)).WithMessage("ServiceDate cannot be more than 5 years ago");

        // Amount validation - reasonable range
        RuleFor(x => x.Amount)
            .GreaterThan(0).WithMessage("Amount must be positive")
            .LessThan(1000000).WithMessage("Amount exceeds maximum allowed");

        // DiagnosisCode validation - ICD-10 format
        RuleFor(x => x.DiagnosisCode)
            .NotEmpty()
            .Matches(@"^[A-Z][0-9]{2}(\.[0-9]{1,4})?$")
            .WithMessage("DiagnosisCode must be valid ICD-10 format");
    }
}

[ApiController]
[Route("api/[controller]")]
public class ClaimsController : ControllerBase
{
    private readonly IClaimsRepository _repository;
    private readonly ILogger<ClaimsController> _logger;

    [HttpPost]
    [Authorize(Policy = "RequireClaimsWriteScope")]
    public async Task<IActionResult> CreateClaim([FromBody] CreateClaimRequest request)
    {
        // Layer 5: Input validation already performed by FluentValidation

        // Layer 5: Parameterized query to prevent SQL injection
        var claim = await _repository.CreateClaimAsync(
            claimId: request.ClaimId,
            memberId: request.MemberId,
            providerId: request.ProviderId,
            serviceDate: request.ServiceDate,
            amount: request.Amount,
            diagnosisCode: request.DiagnosisCode
        );

        // Layer 5: Secure logging - no PHI in logs
        _logger.LogInformation(
            "Claim created successfully. ClaimId: {ClaimId}, Amount: {Amount}",
            claim.ClaimId, claim.Amount
        );

        return CreatedAtAction(nameof(GetClaim), new { claimId = claim.ClaimId }, claim);
    }
}

// Repository with parameterized queries
public class ClaimsRepository : IClaimsRepository
{
    private readonly SqlConnection _connection;

    public async Task<Claim> CreateClaimAsync(
        string claimId, string memberId, string providerId,
        DateTime serviceDate, decimal amount, string diagnosisCode)
    {
        // Layer 5: Parameterized query prevents SQL injection
        const string sql = @"
            INSERT INTO Claims (ClaimId, MemberId, ProviderId, ServiceDate, Amount, DiagnosisCode, CreatedAt)
            VALUES (@ClaimId, @MemberId, @ProviderId, @ServiceDate, @Amount, @DiagnosisCode, @CreatedAt);

            SELECT * FROM Claims WHERE ClaimId = @ClaimId;
        ";

        using var command = new SqlCommand(sql, _connection);
        command.Parameters.AddWithValue("@ClaimId", claimId);
        command.Parameters.AddWithValue("@MemberId", memberId);
        command.Parameters.AddWithValue("@ProviderId", providerId);
        command.Parameters.AddWithValue("@ServiceDate", serviceDate);
        command.Parameters.AddWithValue("@Amount", amount);
        command.Parameters.AddWithValue("@DiagnosisCode", diagnosisCode);
        command.Parameters.AddWithValue("@CreatedAt", DateTime.UtcNow);

        // Execute and return
        using var reader = await command.ExecuteReaderAsync();
        if (await reader.ReadAsync())
        {
            return MapToClaim(reader);
        }
        throw new Exception("Claim creation failed");
    }
}
```

