**Step 3.3: Define ABAC Policies in Rego**

```rego
# OPA Rego policy for fine-grained claims access control
package claims

import future.keywords

# Default deny - explicit grants only
default allow = false

# Allow if user is StateAdmin for the claim's state
allow {
    input.method == "GET"
    input.path == ["claims", claim_id]
    user := data.users[input.user_id]
    claim := data.claims[claim_id]
    user.role == "StateAdmin"
    user.state == claim.state
}

# Allow if user is Provider and claim belongs to their provider ID
allow {
    input.method == "GET"
    input.path == ["claims", claim_id]
    user := data.users[input.user_id]
    claim := data.claims[claim_id]
    user.role == "Provider"
    user.provider_id == claim.provider_id
}

# Allow if user is Member and claim belongs to them
allow {
    input.method == "GET"
    input.path == ["claims", claim_id]
    user := data.users[input.user_id]
    claim := data.claims[claim_id]
    user.role == "Member"
    user.member_id == claim.member_id
}

# Time-based access: Only during business hours for non-emergency access
allow {
    user := data.users[input.user_id]
    user.role != "Emergency"
    time.now_ns() >= business_hours_start
    time.now_ns() <= business_hours_end
}

# Purpose-based access: Only allow if access purpose matches allowed purposes
allow {
    input.purpose in data.users[input.user_id].allowed_purposes
}

# Attribute-based decision with reasoning
decision := {
    "allow": allow,
    "reason": reason,
    "matched_rules": matched_rules
}

reason := sprintf("Access %s. User role: %s, Resource owner: %s",
    [allow_status, user_role, resource_owner])

allow_status := "granted" if allow else "denied"
```

**Step 3.4: Integrate OPA Authorization Handler in ASP.NET Core**

```csharp
// OPA authorization handler (Layer 6: Authorization Security)
using Microsoft.AspNetCore.Authorization;
using System.Net.Http.Json;

public class OpaAuthorizationRequirement : IAuthorizationRequirement { }

public class OpaAuthorizationHandler : AuthorizationHandler<OpaAuthorizationRequirement>
{
    private readonly HttpClient _opaClient;
    private readonly ILogger<OpaAuthorizationHandler> _logger;

    public OpaAuthorizationHandler(IHttpClientFactory httpClientFactory, ILogger<OpaAuthorizationHandler> logger)
    {
        _opaClient = httpClientFactory.CreateClient("OPA");
        _opaClient.BaseAddress = new Uri("http://localhost:8181");
        _logger = logger;
    }

    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        OpaAuthorizationRequirement requirement)
    {
        // Extract user and resource information
        var httpContext = context.Resource as HttpContext;
        if (httpContext == null)
        {
            context.Fail();
            return;
        }

        var userId = context.User.FindFirst("sub")?.Value;
        var userRole = context.User.FindFirst("role")?.Value;
        var userState = context.User.FindFirst("state")?.Value;

        var request = httpContext.Request;
        var resourceId = httpContext.GetRouteValue("claimId")?.ToString();

        // Build OPA input document
        var opaInput = new
        {
            input = new
            {
                method = request.Method,
                path = new[] { "claims", resourceId },
                user_id = userId,
                user_role = userRole,
                user_state = userState,
                purpose = request.Headers["X-Purpose-Of-Use"].FirstOrDefault() ?? "Treatment",
                ip_address = httpContext.Connection.RemoteIpAddress?.ToString(),
                time = DateTime.UtcNow
            }
        };

        // Query OPA for authorization decision
        var response = await _opaClient.PostAsJsonAsync("/v1/data/claims/decision", opaInput);

        if (response.IsSuccessStatusCode)
        {
            var decision = await response.Content.ReadFromJsonAsync<OpaDecision>();

            if (decision?.Result?.Allow == true)
            {
                _logger.LogInformation(
                    "Authorization granted. User: {UserId}, Resource: {ResourceId}, Reason: {Reason}",
                    userId, resourceId, decision.Result.Reason
                );
                context.Succeed(requirement);
            }
            else
            {
                _logger.LogWarning(
                    "Authorization denied. User: {UserId}, Resource: {ResourceId}, Reason: {Reason}",
                    userId, resourceId, decision?.Result?.Reason ?? "Policy denied"
                );
                context.Fail();
            }
        }
        else
        {
            _logger.LogError("OPA authorization check failed. Status: {StatusCode}", response.StatusCode);
            context.Fail();
        }
    }
}

public class OpaDecision
{
    public OpaDecisionResult Result { get; set; }
}

public class OpaDecisionResult
{
    public bool Allow { get; set; }
    public string Reason { get; set; }
    public List<string> MatchedRules { get; set; }
}
```

