**Step 3.7: Implement Tokenization Service**

```csharp
// Tokenization service for sensitive data (Layer 7: Data Security)
using Azure.Security.KeyVault.Keys.Cryptography;
using Azure.Identity;

public interface ITokenizationService
{
    Task<string> TokenizeAsync(string sensitiveData, string dataType);
    Task<string> DetokenizeAsync(string token, string userId, string purpose);
}

public class TokenizationService : ITokenizationService
{
    private readonly SqlConnection _tokenVaultConnection;
    private readonly CryptographyClient _cryptoClient;
    private readonly ILogger<TokenizationService> _logger;

    public TokenizationService(
        string tokenVaultConnectionString,
        string keyVaultUrl,
        ILogger<TokenizationService> logger)
    {
        _tokenVaultConnection = new SqlConnection(tokenVaultConnectionString);
        _cryptoClient = new CryptographyClient(
            new Uri($"{keyVaultUrl}/keys/tokenization-key"),
            new DefaultAzureCredential()
        );
        _logger = logger;
    }

    public async Task<string> TokenizeAsync(string sensitiveData, string dataType)
    {
        // Generate random token
        var token = Guid.NewGuid().ToString("N");

        // Encrypt sensitive data
        var encryptResult = await _cryptoClient.EncryptAsync(
            EncryptionAlgorithm.RsaOaep256,
            Encoding.UTF8.GetBytes(sensitiveData)
        );

        // Store token mapping in secure vault
        const string sql = @"
            INSERT INTO TokenVault (Token, EncryptedValue, DataType, CreatedAt)
            VALUES (@Token, @EncryptedValue, @DataType, @CreatedAt);
        ";

        using var command = new SqlCommand(sql, _tokenVaultConnection);
        command.Parameters.AddWithValue("@Token", token);
        command.Parameters.AddWithValue("@EncryptedValue", encryptResult.Ciphertext);
        command.Parameters.AddWithValue("@DataType", dataType);
        command.Parameters.AddWithValue("@CreatedAt", DateTime.UtcNow);

        await command.ExecuteNonQueryAsync();

        _logger.LogInformation("Tokenized {DataType}. Token: {Token}", dataType, token);

        return token;
    }

    public async Task<string> DetokenizeAsync(string token, string userId, string purpose)
    {
        // Retrieve encrypted value from vault
        const string sql = @"
            SELECT EncryptedValue FROM TokenVault WHERE Token = @Token;

            INSERT INTO TokenAccessLog (Token, UserId, Purpose, AccessedAt)
            VALUES (@Token, @UserId, @Purpose, @AccessedAt);
        ";

        using var command = new SqlCommand(sql, _tokenVaultConnection);
        command.Parameters.AddWithValue("@Token", token);
        command.Parameters.AddWithValue("@UserId", userId);
        command.Parameters.AddWithValue("@Purpose", purpose);
        command.Parameters.AddWithValue("@AccessedAt", DateTime.UtcNow);

        using var reader = await command.ExecuteReaderAsync();
        if (!await reader.ReadAsync())
        {
            throw new UnauthorizedAccessException("Token not found");
        }

        var encryptedValue = (byte[])reader["EncryptedValue"];

        // Decrypt sensitive data
        var decryptResult = await _cryptoClient.DecryptAsync(
            EncryptionAlgorithm.RsaOaep256,
            encryptedValue
        );

        _logger.LogWarning(
            "Detokenized data. Token: {Token}, User: {UserId}, Purpose: {Purpose}",
            token, userId, purpose
        );

        return Encoding.UTF8.GetString(decryptResult.Plaintext);
    }
}
```

