**Layer 5 - Application Security with Offline Support**:
```typescript
// Mobile app with offline-first architecture and local encryption
import * as SecureStore from 'expo-secure-store';
import CryptoJS from 'crypto-js';

class SecureOfflineStorage {
  private encryptionKey: string;

  async initialize() {
    // Generate device-specific encryption key
    this.encryptionKey = await SecureStore.getItemAsync('encryption_key');
    if (!this.encryptionKey) {
      this.encryptionKey = CryptoJS.lib.WordArray.random(256/8).toString();
      await SecureStore.setItemAsync('encryption_key', this.encryptionKey);
    }
  }

  async cacheHealthData(data: HealthRecord[]) {
    // Encrypt data before storing offline
    const encrypted = CryptoJS.AES.encrypt(
      JSON.stringify(data),
      this.encryptionKey
    ).toString();

    await SecureStore.setItemAsync('cached_health_data', encrypted);
  }

  async retrieveCachedData(): Promise<HealthRecord[]> {
    const encrypted = await SecureStore.getItemAsync('cached_health_data');
    if (!encrypted) return [];

    const decrypted = CryptoJS.AES.decrypt(encrypted, this.encryptionKey);
    return JSON.parse(decrypted.toString(CryptoJS.enc.Utf8));
  }
}
```

