// Return data with appropriate masking based on user context
public async Task<MemberHealthRecordResponse> GetHealthRecordsAsync(string memberId, ClaimsPrincipal user)
{
    var records = await _repository.GetHealthRecordsAsync(memberId);

    // Mask sensitive fields for non-authenticated family members
